import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xhi23')
from lib import *
r=[]
r.append(R(6595296,"शहद-सरसों वाली चिकन थाई और वाइल्ड राइस",
"हनी डिजॉन सरसों इन चिकन थाई को मीठा और चटपटा बना देती है। वाइल्ड राइस और भाप में पकी ब्रोकली मिलाने से यह एक संपूर्ण, संतुलित भोजन बन जाता है।",
"4","1 चिकन थाई + ½ कप वाइल्ड राइस + 1 कप ब्रोकली",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/4 कप हनी डिजॉन सरसों","2 फांक लहसुन (बारीक कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1 पाउंड बिना हड्डी और बिना त्वचा की चिकन थाई","3/4 छोटा चम्मच सूखा थाइम","2 कप पका हुआ वाइल्ड राइस (पैकेट पर दिए निर्देशों के अनुसार तैयार)","4 कप ब्रोकली (भाप में पकी)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","एक छोटे कटोरे में सरसों, लहसुन और काली मिर्च मिलाएँ।","हर चिकन थाई के ऊपर लगभग 1 1/2 बड़े चम्मच सरसों का मिश्रण समान रूप से फैलाएँ।","चिकन को काँच की बेकिंग डिश में सजाएँ। 40 मिनट तक बेक करें, या जब तक सरसों का मिश्रण परत बनकर थोड़ा सख़्त न हो जाए।","ओवन से निकालें और चिकन के ऊपर थाइम छिड़कें। हर चिकन थाई को 1/2 कप वाइल्ड राइस और 1 कप भाप में पकी ब्रोकली के साथ परोसें।"]))
r.append(R(6595377,"एशियन चिकन सलाद",
"क्या आप हर दिन काम पर वही उबाऊ लंच ले जाकर थक गए हैं? ज़्यादातर लोग सेहतमंद खाने की कोशिश में इसलिए ऊब जाते हैं क्योंकि वे अपने खाने में पर्याप्त विविधता नहीं रखते। बेहतरीन स्वाद वाले बदलाव के लिए यह स्वादिष्ट सलाद आज़माएँ।",
"4","2 कप",
["9 औंस रोमेन लेट्यूस (कटा हुआ)","1 कप पत्ता गोभी (बारीक कतरी हुई)","1 कप कद्दूकस की हुई गाजर","1/4 कप बादाम के पतले टुकड़े (भुने हुए)","1 बड़ा चम्मच और 1 छोटा चम्मच भुने हुए तिल (बाँटकर इस्तेमाल करें)","2 कप पका हुआ चिकन ब्रेस्ट (छोटे टुकड़ों में कटा)","2 बड़े चम्मच राइस विनेगर","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1/4 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स","2 बड़े चम्मच ज़ैतून का तेल"],
["एक मध्यम कटोरे में पत्ता गोभी, लेट्यूस, बादाम, 1 बड़ा चम्मच तिल और चिकन को अच्छी तरह मिलाएँ।","एक छोटे कटोरे में सिरका, सोया सॉस और तेल को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद पर डालें और अच्छी तरह मिलाएँ ताकि सब पर लग जाए। ऊपर से बचे हुए 1 छोटे चम्मच तिल और लाल मिर्च के फ्लेक्स डालें।"]))
r.append(R(6597568,"पालक के साथ क्रीमी टस्कन चिकन",
"कम वसा वाले दूध और ग्रीक योगर्ट के मेल की वजह से इस टस्कन चिकन में भारी क्रीम के बिना भी क्रीमी, आरामदायक स्वाद मिलता है। कम वसा वाले प्रोटीन, फाइबर से भरपूर पालक और बिना अतिरिक्त चीनी के यह एक संतुलित व्यंजन है, जो आपको अपने ब्लड ग्लूकोज़ (रक्त शर्करा) के लक्ष्य तक पहुँचने में मदद करेगा। अगर आप कुछ पेट भरने वाला, स्वादिष्ट और मधुमेह के अनुकूल खाना चाहते हैं, तो यह एक बढ़िया विकल्प है।",
"4","4 औंस चिकन + 1/2 कप सॉस",
["1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट","1/2 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच सूखा ओरेगैनो","1 छोटा चम्मच ज़ैतून का तेल","3 फांक लहसुन (बारीक कटा हुआ)","12 औंस कम सोडियम वाला चिकन ब्रॉथ (वसा रहित)","1/2 कप 1% वसा वाला दूध","1 बड़ा चम्मच कॉर्नस्टार्च","1/4 कप सन-ड्राइड टमाटर (बिना तेल के, कटे हुए)","1/2 छोटा चम्मच कुटी हुई लाल मिर्च के फ्लेक्स (वैकल्पिक)","2 कप बेबी पालक (कटा हुआ)","1/4 कप पार्मेसन चीज़ (कद्दूकस किया हुआ)","1/4 कप सादा बिना वसा वाला ग्रीक योगर्ट","1/2 कप ताज़ी तुलसी (हाथ से फाड़ी हुई, परोसने के लिए और भी)"],
["चिकन ब्रेस्ट पर काली मिर्च, लहसुन पाउडर और ओरेगैनो छिड़कें। एक बड़े स्किलेट में मध्यम आँच पर ज़ैतून का तेल गरम करें। चिकन डालें और सुनहरा भूरा होने तक सेकें, जब तक अंदर का तापमान 165 डिग्री F तक न पहुँच जाए, हर तरफ़ लगभग 4–5 मिनट। इसे एक प्लेट में निकाल लें।","उसी स्किलेट में लहसुन डालें और खुशबू आने तक लगभग 30 सेकंड पकाएँ। चिकन ब्रॉथ डालें और तली में चिपके भूरे अंश खुरचकर मिला लें। दूध, सन-ड्राइड टमाटर और लाल मिर्च के फ्लेक्स डालकर चलाएँ। 2–3 मिनट तक धीमी आँच पर उबालें।","पालक और पार्मेसन चीज़ डालें और पालक के गलने तक लगभग 1–2 मिनट पकाएँ।","सॉस के उबल जाने के बाद पैन को आँच से उतार लें। एक छोटे कटोरे में ¼ कप सादा ग्रीक योगर्ट को 1–2 बड़े चम्मच गरम सॉस के साथ मिलाएँ ताकि वह सॉस के तापमान के अनुकूल हो जाए। अब इस योगर्ट को धीरे-धीरे पैन में डालें और पूरी तरह मिलने तक हल्के हाथ से चलाएँ।","चिकन को वापस पैन में डालें। सॉस को चिकन के ऊपर चम्मच से डालें। आधी तुलसी डालें और गरम होने तक 1–2 मिनट धीमी आँच पर पकाएँ।","ऊपर से और ताज़ी तुलसी डालकर परोसें।"]))
r.append(R(6598291,"चिकन और डम्पलिंग्स",
"परिवार के किफ़ायती डिनर के लिए ये चिकन और डम्पलिंग्स आज़माएँ। अपना भोजन पूरा करने के लिए साथ में भुनी हुई हरी फलियाँ परोसें।",
"8","1 1/2 कप",
["1 कप गेहूँ का आटा (साबुत)","1/2 कप मैदा (ऑल-पर्पज़ आटा)","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच पिसा हुआ सेज","1/4 छोटा चम्मच कोशर नमक (वैकल्पिक)","1/4 छोटा चम्मच काली मिर्च","1/2 कप सादा बिना वसा वाला ग्रीक योगर्ट","1 बड़ा अंडा","1 बड़ा चम्मच ठंडा पानी","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 छोटा चम्मच ज़ैतून का तेल","1 मध्यम प्याज़ (कटा हुआ)","2 मध्यम गाजर (कटी हुई)","2 डंठल अजवाइन (सेलरी) (कटे हुए)","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1 1/2 पाउंड चिकन ब्रेस्ट (बिना हड्डी और बिना त्वचा के, कटे हुए)","8 कप कम सोडियम वाला चिकन ब्रॉथ (वसा रहित, कम सोडियम)"],
["एक मध्यम कटोरे में दोनों आटे, बेकिंग सोडा, बेकिंग पाउडर, सेज, नमक (वैकल्पिक) और काली मिर्च मिलाएँ। योगर्ट, अंडा और पानी डालकर गूँधें और थोड़ा चिपचिपा आटा तैयार करें। कटोरे को ढककर एक तरफ़ रख दें।","एक बड़े सूप के बर्तन में मध्यम-तेज़ आँच पर कुकिंग स्प्रे और ज़ैतून का तेल डालें। प्याज़, गाजर, अजवाइन और मशरूम डालें। सब्ज़ियों के नरम होने तक 5-7 मिनट भूनें।","चिकन और ब्रॉथ डालें और उबाल आने दें। फिर आँच धीमी करके 5 मिनट तक उबलने दें।","आटे को बेलकर 8 इंच की, 1/2 इंच मोटी गोल लोई बना लें। आटे को 1 इंच के टुकड़ों में काटें और डम्पलिंग्स को उबलते ब्रॉथ में डालें। सभी डम्पलिंग्स डालने तक बार-बार चलाते रहें।","डम्पलिंग्स को 10 मिनट तक उबलने दें और परोसें।"]))
r.append(R(6599227,"भुनी शिमला मिर्च और केपर्स का सलाद",
"इटैलियन शैली का यह सलाद आपकी थाली में कुछ बिना स्टार्च वाली सब्ज़ियाँ जोड़ने का बढ़िया तरीका है। कार्बोहाइड्रेट में कम, लेकिन स्वाद में भरपूर, इस ताज़े और सेहतमंद विकल्प का आपका पूरा परिवार आनंद लेगा।",
"4","1 कप",
["3 मध्यम शिमला मिर्च (अलग-अलग रंगों की)","2 बड़े चम्मच केपर्स (पानी निथारे हुए)","1/4 कप कलामाता जैतून (बीज निकालकर कटे हुए)","1/4 कप ताज़ा अजमोद (पार्सले) (कटा हुआ)","2 बड़े चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1 बड़ा चम्मच रेड वाइन विनेगर","1 फांक लहसुन (बारीक कटा हुआ)","1/8 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
["ओवन का ब्रॉयलर पहले से चालू करें। साबुत शिमला मिर्च को बेकिंग शीट पर रखें और बीच-बीच में पलटते हुए ब्रॉयल करें, जब तक छिलका जलकर फफोले जैसा न हो जाए। ओवन से निकालकर ठंडा होने दें। ठंडा होने पर छिलका उतारें, बीज निकालें और पट्टियों में काट लें।","एक कटोरे में भुनी शिमला मिर्च की पट्टियाँ, निथारे हुए केपर्स, कटे हुए कलामाता जैतून और कटा हुआ ताज़ा अजमोद मिलाएँ।","एक छोटे कटोरे में एक्स्ट्रा वर्जिन ज़ैतून का तेल, रेड वाइन विनेगर, बारीक कटा लहसुन, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को भुनी शिमला मिर्च के मिश्रण पर डालें। हल्के हाथ से मिलाएँ ताकि ड्रेसिंग सब पर समान रूप से लग जाए।","स्वाद आपस में घुल-मिल जाएँ, इसके लिए सलाद को कम से कम 15 मिनट मैरिनेट होने दें।"]))
r.append(R(6600449,"चिकन और भुनी शिमला मिर्च के लेट्यूस कप",
"यह रेसिपी नैन्सी एस. ह्यूज़ की पुस्तक \"Designed for One!\" में प्रकाशित हुई थी।",
"1","2 लेट्यूस कप",
["4 औंस चिकन कटलेट","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 औंस भुनी हुई लाल शिमला मिर्च (कटी हुई)","1/3 कप काबुली चना (बिना नमक मिलाए, धोकर निथारे हुए)","2 बड़े चम्मच लाल प्याज़ (बारीक कटा हुआ)","4 पूरे बीज निकले कलामाता जैतून (मोटे कटे हुए)","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई)","2 छोटे चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1 छोटा चम्मच रेड वाइन विनेगर","2 पत्ते रोमेन या बोस्टन लेट्यूस के पत्ते"],
["एक छोटे नॉनस्टिक स्किलेट को मध्यम आँच पर गरम करें। चिकन के दोनों तरफ़ कुकिंग स्प्रे लगाएँ और हर तरफ़ 4 मिनट पकाएँ, या जब तक बीच में गुलाबीपन न रह जाए। इसे कटिंग बोर्ड पर रखें, 2–3 मिनट ठंडा होने दें और काट लें।","इस बीच, लेट्यूस के पत्तों को छोड़कर बाकी सारी सामग्री एक कटोरे में मिला लें।","परोसने के लिए, हर पत्ते में कटा हुआ चिकन रखें और ऊपर से शिमला मिर्च का मिश्रण डालें।"]))
r.append(R(6601352,"बिना आटे के ब्राउनीज़",
"भरपूर और लज़ीज़, ये बिना आटे के ब्राउनीज़ एक मनपसंद मिठाई हैं जो मधुमेह के अनुकूल भी है।",
"16","1 ब्राउनी (½ इंच x ½ इंच)",
["1/2 कप वनस्पति तेल","1 1/2 कप कैरोब चिप्स","1/2 कप चीनी का विकल्प","3 बड़े अंडे","2 छोटे चम्मच वनीला एक्सट्रैक्ट","1/2 कप बिना मीठा कोको पाउडर (बिना चीनी वाला)"],
["ओवन को 350°F पर गरम करें। 8x8 इंच के बेकिंग पैन में बेकिंग पेपर बिछाएँ और किनारों पर थोड़ा कागज़ बाहर रहने दें ताकि ब्राउनीज़ आसानी से निकल सकें।","वनस्पति तेल और कैरोब चिप्स को एक मध्यम कटोरे में डालकर उबलते पानी के बर्तन के ऊपर रखें। धीरे-धीरे लगातार चलाते हुए कैरोब चिप्स को तेल के साथ पिघलाएँ। पिघल जाने पर कटोरे को बर्तन से उतारें और उसकी तली पोंछकर सुखा लें।","चीनी का विकल्प फेंटकर मिलाएँ, फिर एक-एक करके अंडे डालें, जब तक घोल चिकना न हो जाए।","वनीला एक्सट्रैक्ट और कोको पाउडर डालकर मिलाएँ।","घोल को बेकिंग डिश में समान रूप से फैलाएँ। 15-18 मिनट बेक करें, या जब तक बीच में डाली गई टूथपिक साफ़ बाहर न आए। इसे पैन में ही पूरी तरह ठंडा होने दें।","बेकिंग पेपर के किनारे पकड़कर ब्राउनीज़ को पैन से बाहर उठा लें। काटें और परोसें।"]))
r.append(R(6602493,"नींबू-हर्ब विनिग्रेट के साथ फलाफल सलाद",
"यह सलाद कुरकुरी सब्ज़ियों, गरम जड़ी-बूटियों से भरे चने की टिक्कियों (फलाफल) और चटपटे नींबू विनिग्रेट से भरपूर है, जो इसे एक संतोषजनक भोजन बनाता है। तलने की बजाय बेक किए गए फलाफल इसे हल्का रखते हैं, फिर भी फाइबर और पौधों से मिलने वाला प्रोटीन देते हैं। इसमें अतिरिक्त चीनी नहीं है और कार्बोहाइड्रेट धीरे-धीरे पचते हैं, इसलिए यह दोपहर या रात के भरपूर भोजन के लिए मधुमेह के अनुकूल विकल्प है।",
"4","1 1/2 कप सलाद + 3 1/2 फलाफल",
["1 कप डिब्बाबंद काबुली चना (बिना नमक मिलाए, निथारे और धोए हुए)","1 छोटा पीला प्याज़ (छोटे टुकड़ों में कटा)","3 फांक लहसुन (बारीक कटा हुआ, बाँटकर इस्तेमाल करें)","1 1/4 कप ताज़ा अजमोद (पार्सले) (बाँटकर इस्तेमाल करें)","1 कप ताज़ा हरा धनिया","1 छोटा चम्मच पिसा हुआ जीरा","1 छोटा चम्मच पिसा हुआ धनिया","1/2 छोटा चम्मच नमक (बाँटकर इस्तेमाल करें)","1/2 छोटा चम्मच काली मिर्च (बाँटकर इस्तेमाल करें)","1 छोटा चम्मच बेकिंग पाउडर","2 बड़े चम्मच मैदा (ऑल-पर्पज़ आटा)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","3 बड़े चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","2 बड़े चम्मच नींबू का रस (ताज़ा)","1 छोटा चम्मच डिजॉन सरसों","1 बड़ा चम्मच ताज़ा सोआ (डिल)","8 कप रोमेन लेट्यूस (कटा हुआ)","1 कप चेरी टमाटर (आधे कटे हुए)","1 मध्यम खीरा (छोटे टुकड़ों में कटा)","1/4 कप लाल प्याज़ (पतला कटा हुआ)"],
["ओवन को 450 डिग्री F पर पहले से गरम करें।","चने को फ़ूड प्रोसेसर में 1 छोटे पीले प्याज़, 2 फांक लहसुन, जड़ी-बूटियों और मसालों (1 कप ताज़ी अजमोद की पत्तियाँ, 1 कप ताज़ी हरे धनिए की पत्तियाँ, 1 छोटा चम्मच पिसा जीरा, 1 छोटा चम्मच पिसा धनिया, ¼ छोटा चम्मच नमक, ¼ छोटा चम्मच काली मिर्च) के साथ डालें। तब तक पल्स करें जब तक मिश्रण दरदरा न हो जाए और दबाने पर आपस में जुड़ने न लगे।","बेकिंग पाउडर और मैदा डालकर थोड़ा-सा पल्स करके मिला लें। कम से कम 1 घंटे के लिए ठंडा करें।","इसे छोटी गोलियों या टिक्कियों (लगभग 1–1.5 इंच चौड़ी) का आकार दें। बेकिंग शीट पर रखें और 12–16 फलाफल बनने तक यही दोहराएँ।","फलाफल पर कुकिंग स्प्रे करें। ओवन की सबसे निचली रैक पर 15 मिनट बेक करें। ओवन को 350 डिग्री F पर कर दें और बेकिंग शीट को ऊपरी रैक पर रखें। 15 मिनट और बेक करें।","इस बीच, एक छोटे जार या कटोरे में ज़ैतून का तेल, नींबू का रस, सरसों, बचा हुआ लहसुन और 1 बड़ा चम्मच कटा हुआ ताज़ा सोआ मिलाएँ। इसे हिलाकर या फेंटकर एकसार कर लें। 1/8 छोटा चम्मच नमक और 1/8 छोटा चम्मच काली मिर्च से स्वाद बनाएँ।","परोसने के लिए, रोमेन, टमाटर, खीरा, लाल प्याज़ और ¼ कप कटा हुआ ताज़ा अजमोद कटोरों में बराबर बाँट लें।","ऊपर से नींबू-हर्ब विनिग्रेट डालें और अच्छी तरह मिलाएँ। ऊपर गरम फलाफल रखकर तुरंत परोसें।"]))
r.append(R(6604257,"शकरकंद और पालक वाले चिकन टैकोज़",
"फ़ूड ट्रक की दुनिया में टैको की अनोखी फ़िलिंग्स की आजकल बहुत धूम है। इन भरपूर और चटपटे टैकोज़ को घर पर बनाइए!",
"4","1 टैको",
["1 1/2 बड़े चम्मच ज़ैतून का तेल","1 फांक लहसुन (बारीक कटा हुआ)","24 औंस बेबी पालक","1 बड़ा शकरकंद (छिला और छोटे टुकड़ों में कटा)","1/4 छोटा चम्मच जीरा","1/4 छोटा चम्मच काली मिर्च","4 बड़े चम्मच पानी","1 कप पका हुआ कतरा हुआ चिकन","4 छोटी 6 इंच की मक्के की टॉर्टिला (गरम की हुई)","4 छोटे चम्मच लाइट सावर क्रीम","1/2 कप पिको डे गायो या सालसा"],
["एक बड़े नॉनस्टिक पैन में मध्यम आँच पर तेल गरम करें। लहसुन डालकर 30 सेकंड भूनें। पालक डालकर 3 से 4 मिनट भूनें।","पैन में शकरकंद, जीरा, काली मिर्च और पानी डालें। 2 मिनट भूनें। ढक दें, आँच धीमी करें और 8 मिनट पकाएँ।","पैन में चिकन डालकर मिला लें। 2 मिनट गरम करें।","हर टॉर्टिला में चिकन और शकरकंद के मिश्रण का 1/4 हिस्सा भरें। ऊपर 1 छोटा चम्मच सावर क्रीम और 2 बड़े चम्मच पिको डे गायो डालें।"]))
r.append(R(6604490,"मीठी-तीखी सॉस के साथ नारियल-बादाम चिकन टेंडर्स",
"मीठा नारियल और बादाम तीखी सॉस के साथ बेहतरीन मेल बनाते हैं और इन चिकन टेंडर्स को एक अलग ही स्तर पर पहुँचा देते हैं।",
"4","2 चिकन टेंडर्स + 2 बड़े चम्मच सॉस",
["2 पूरे बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (8 पट्टियों में कटे, हर एक 1 इंच की)","1/2 कप ब्रेड क्रम्ब्स (गेहूँ के)","2 बड़े चम्मच बिना मीठे नारियल के फ्लेक्स","1/2 कप बादाम (कटे हुए)","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच काली मिर्च","2 बड़े अंडे","1/3 कप खुबानी का जैम (बिना अतिरिक्त चीनी का)","2 बड़े चम्मच गार्लिक चिली सॉस (स्वादानुसार)","1/4 छोटा चम्मच कोशर नमक"],
["ओवन को 400 डिग्री F पर गरम करें और शीट पैन पर बेकिंग पेपर बिछाएँ।","एक मध्यम कटोरे में अंडों को फेंट लें।","दूसरे मध्यम कटोरे में पैंको, कसा हुआ नारियल, कटे हुए बादाम और लहसुन पाउडर को फेंटकर मिलाएँ।","हर चिकन पट्टी को पहले अंडे में और फिर नारियल के मिश्रण में डुबोएँ, और अच्छी तरह चूरे की परत चढ़ाएँ।","इन्हें बेकिंग शीट पर रखें और तब तक बेक करें जब तक टेंडर्स का अंदरूनी तापमान 165 डिग्री F न हो जाए, लगभग 15 मिनट।","डिपिंग सॉस के लिए खुबानी का जैम, गार्लिक चिली सॉस और कोशर नमक को फेंटकर मिलाएँ। चाहें तो 1-2 बड़े चम्मच पानी मिलाकर पतला करें और छान लें।","डिपिंग सॉस के साथ परोसें।"]))
r.append(R(6605420,"देशी भरवाँ समर स्क्वैश",
"पैकेट वाला कॉर्नब्रेड स्टफ़िंग मिक्स इस्तेमाल करने से यह साइड डिश आसानी से बन जाती है। यह स्वादिष्ट गर्मियों की साइड डिश है जिसे आप सप्ताह के किसी भी दिन बना सकते हैं। मज़ेदार स्टार्टर के लिए बेबी स्क्वैश लें और संख्या दोगुनी कर दें, या परोसने से पहले सामान्य स्क्वैश को 2 इंच के टुकड़ों में काट लें।",
"4","स्क्वैश का 1 आधा भाग",
["2 बड़े ज़ुकीनी या पीले समर स्क्वैश (लंबाई में आधे कटे, कुल 12 औंस; कोई भी किस्म लें, जैसे पीला, स्कैलप या ज़ुकीनी)","1 कप लाल या हरी शिमला मिर्च (कटी हुई)","1/2 कप पानी","2 बड़े चम्मच ट्रांस-फैट रहित मार्जरीन (35% वनस्पति तेल)","1 कप कॉर्नब्रेड स्टफ़िंग मिक्स (सूखा)"],
["ओवन को 350°F पर पहले से गरम करें।","स्क्वैश का गूदा चम्मच से निकालें और मोटा-मोटा काट लें।","एक मध्यम नॉनस्टिक स्किलेट को मध्यम-तेज़ आँच पर गरम होने तक रखें। स्किलेट पर नॉनस्टिक कुकिंग स्प्रे लगाएँ और स्क्वैश का गूदा और शिमला मिर्च डालें। शिमला मिर्च के नरम-कुरकुरी होने तक 4 मिनट बार-बार चलाते हुए पकाएँ।","स्किलेट को आँच से उतारें और पानी तथा मार्जरीन मिलाएँ। स्टफ़िंग मिक्स डालकर काँटे से धीरे से मिलाएँ। हर स्क्वैश के आधे हिस्से में 1/2 कप स्टफ़िंग चम्मच से भरें। हल्के से दबाएँ ताकि स्टफ़िंग चिपक जाए।","स्किलेट पर दोबारा नॉनस्टिक कुकिंग स्प्रे लगाएँ, भरवाँ स्क्वैश को उसमें सजाएँ, कसकर ढक दें और 30 मिनट बेक करें, या जब तक काँटे से चुभोने पर स्क्वैश नरम न लगे।"]))
r.append(R(6605632,"बेक्ड चाय मसाला सेब चिप्स",
"बेक्ड सेब चिप्स कुरकुरे और मीठे स्वाद का एक लज़ीज़ नाश्ता है। इस रेसिपी में चाय मसाले का स्वाद जोड़ा गया है, जो मसालों का एक गर्माहट देने वाला मिश्रण है और पतझड़ व सर्दियों के मौसम के सेहतमंद नाश्ते के लिए एकदम सही है।",
"4","7 स्लाइस",
["2 मध्यम सेब (फ़ूजी या हनीक्रिस्प जैसी मीठी किस्में)","2 छोटे चम्मच पिसी दालचीनी","1/2 छोटा चम्मच पिसी इलायची","1/2 छोटा चम्मच पिसी अदरक (सोंठ)","1/4 छोटा चम्मच पिसी लौंग","1/4 छोटा चम्मच पिसी जायफल"],
["ओवन को 200 डिग्री F पर पहले से गरम करें और दो बेकिंग शीट पर बेकिंग पेपर बिछाएँ। चिपकने से रोकने के लिए आप बेकिंग पेपर पर हल्का-सा कुकिंग स्प्रे भी लगा सकते हैं।","सेबों को धोएँ और उनके बीज व डंठल निकालकर कोर हटा दें। अतिरिक्त बनावट और पोषक तत्वों के लिए आप छिलका रख सकते हैं। मैंडोलिन स्लाइसर या तेज़ चाकू से सेबों को लगभग 1/8 इंच मोटाई के गोल पतले स्लाइस में काटें। सभी स्लाइस एक जैसे पतले हों ताकि वे बराबर सिकें।","एक छोटे कटोरे में पिसी दालचीनी, पिसी इलायची, पिसी अदरक, पिसी लौंग और पिसा जायफल मिलाकर चाय मसाले का मिश्रण बना लें।","सेब के स्लाइस को तैयार बेकिंग शीट पर एक परत में बिछाएँ, ध्यान रखें कि वे एक-दूसरे पर न चढ़ें। चाय मसाले का मिश्रण स्लाइस पर समान रूप से छिड़कें। मसाले बराबर फैलाने के लिए आप उँगलियों या शेकर का उपयोग कर सकते हैं।","बेकिंग शीट को पहले से गरम ओवन में रखें और लगभग 2 घंटे बेक करें। बीच-बीच में सेब चिप्स को देखते रहें ताकि वे ज़्यादा न पक जाएँ। चिप्स तब तैयार हैं जब वे कुरकुरे हो जाएँ पर जले नहीं। ठंडे होने पर वे और भी कुरकुरे हो जाएँगे।"]))
